"""Evaluate layered configuration requests against a supplied policy."""

from copy import deepcopy


def _failure(error):
    return {"ok": False, "config": {}, "error": error}


def _matches_type(value, expected):
    if expected == "boolean":
        return type(value) is bool
    if expected == "integer":
        # bool is a subclass of int in Python, so use an exact type check.
        return type(value) is int
    if expected == "string":
        return type(value) is str
    return False


def _parse_environment(value, expected):
    if type(value) is not str:
        raise ValueError

    if expected == "boolean":
        if value == "true":
            return True
        if value == "false":
            return False
        raise ValueError

    if expected == "integer":
        digits = value[1:] if value.startswith("-") else value
        if not digits or not digits.isascii() or not digits.isdigit():
            raise ValueError
        return int(value)

    if expected == "string":
        return value

    raise ValueError


def evaluate(request, policy):
    """Apply request layers and environment overrides using policy."""
    defaults = policy["defaults"]
    expected_types = policy["types"]
    known = set(defaults)
    config = deepcopy(defaults)

    for layer in request.get("layers", []):
        for key, value in layer.items():
            if key not in known:
                return _failure("unknown_key")
            if value is None and policy.get("null_resets") is True:
                config[key] = deepcopy(defaults[key])
            else:
                config[key] = value

    environment = request.get("environment", {})
    if environment:
        # Unknown keys always use the dedicated error, even when environment
        # overrides are disabled by the policy.
        if any(key not in known for key in environment):
            return _failure("unknown_key")
        if policy.get("environment") is not True:
            return _failure("environment")
        for key, value in environment.items():
            try:
                config[key] = _parse_environment(value, expected_types.get(key))
            except (TypeError, ValueError):
                return _failure("environment")

    for key, value in config.items():
        if not _matches_type(value, expected_types.get(key)):
            return _failure("type")

    return {"ok": True, "config": config, "error": None}

